Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='conflictmarkers', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='Rebuild a code conflict from the two whole versions, never by deleting markers', body="A conflict hunk is a text region, not a block of code. Rebuild the file from the base version and the other side's complete addition. Deleting markers is safe only in list files where each side is a whole item, such as a changelog. Run the checks bare after a merge and read their exit code.", rationale='A hunk can end in the middle of a statement, and a stripped marker then merges a file that does not compile.', supersedes=()))